CREATE TABLE IF NOT EXISTS live_scoreboard_bridge (id TEXT PRIMARY KEY,token_hash TEXT,session_id TEXT,config_id TEXT,match_id TEXT NOT NULL DEFAULT '',last_sequence INTEGER NOT NULL DEFAULT -1,snapshot TEXT,last_seen_at INTEGER NOT NULL DEFAULT 0,sample_at INTEGER NOT NULL DEFAULT 0,received_at INTEGER NOT NULL DEFAULT 0,source_status TEXT NOT NULL DEFAULT 'waiting',source_error TEXT NOT NULL DEFAULT '',diagnostic TEXT);
